import { ticket_manegement_plots } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriessubAddition: Boolean
  },
  data() {
    return {
      ploatName: "",
      loading: false
    };
  },
  watch: {
    categoriessubAddition: {
      async handler() {
        await this.fetch_categories();
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(ticket_manegement_plots, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "CREATE",
            plot_name: this.ploatName
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.ticket_manegement_plots);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "update");
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
